  "project": "FM-Agent",
  "languages": ["python"],
  "file_extensions": ["py"],
  "phases": [
    {
      "phase": 1,
      "name": "Environment & Pipeline Setup",
      "description": "Initializes the runtime environment, validates prerequisites, manages git worktrees, discovers source files, generates the analysis phase plan and domain context for target codebases, and provides shared LLM communication and trace infrastructure.",
      "modules": [
        {
          "name": "pipeline_setup",
          "description": "Orchestrates the Phase Plan generation and Domain Context workflows for a target codebase by invoking OpenCode agents that analyze the project structure and produce phases.json and per-phase domain context files. Also handles post-processing such as deduplication of source files across phases, syncing domain context when phases change, and compliance validation.",
          "source_files": ["src/pipeline_setup.py"]
        },
        {
          "name": "env_check",
          "description": "Validates that the runtime environment meets all prerequisites before pipeline execution: verifies the LLM API key is set, checks that required model backends (OpenCode, Codex CLI, or Claude CLI) are installed, and ensures necessary plugins and language toolchains are available.",
          "source_files": ["src/env_check.py"]
        },
        {
          "name": "domain_knowledge",
          "description": "Collects, stages, and formats user-provided domain knowledge files (Markdown documents describing project-specific invariants, protocols, or terminology). Copies them into the workspace under spec_prompts/domain_context/user_knowledge/ and provides formatting utilities for injecting them into agent prompts.",
          "source_files": ["src/domain_knowledge.py"]
        },
        {
          "name": "cli_backend",
          "description": "Detects the available CLI backend (OpenCode, Codex CLI, or Claude CLI) and builds the appropriate command-line invocation strings. Handles model/provider prefix mapping and reasoning-effort flag construction for each backend.",
          "source_files": ["src/cli_backend.py"]
        },
        {
          "name": "git",
          "description": "Provides git operations for the pipeline: checks whether a directory is a git repository, creates isolated worktree snapshots for safe analysis, retrieves HEAD commit IDs for version tracking, and records processed commits to version.log for incremental mode baselines.",
          "source_files": ["src/git.py"]
        },
        {
          "name": "file_utils",
          "description": "Shared file discovery and filtering utilities used throughout the pipeline. Enumerates project source files by extension, filters out test files, checks whether extracted function files have received [SPEC] annotations, collects file lists per phase, and validates JSON files for structural integrity.",
          "source_files": ["src/file_utils.py"]
        },
        {
          "name": "llm_client",
          "description": "Low-level LLM API client with automatic retry logic, provider detection, and JSON response parsing. Handles model string canonicalization, builds CLI invocation commands for OpenCode/Codex/Claude backends, and parses structured JSON responses from LLM calls with support for direct, fenced, and prose-wrapped formats.",
          "source_files": ["src/llm_client.py"]
        },
        {
          "name": "opencode_trace",
          "description": "Wraps OpenCode process invocation with structured tracing metadata. Records each call's stage, input/output files, function IDs, attempt count, and timing into the trace event stream. Provides file-path-to-function-ID canonicalization for trace consistency.",
          "source_files": ["src/opencode_trace.py"]
        },
        {
          "name": "trace_writer",
          "description": "Writes structured execution trace events (OpenCode calls, LLM exchanges, verification attempts) to a JSONL event log under fm_agent/trace/. Generates unique event IDs, timestamps, and manages a payload subdirectory for storing large event payloads such as OpenCode stdout and selected LLM messages.",
          "source_files": ["src/trace_writer.py"]
        }
      ],
      "depends_on_phases": []
    },
    {
      "phase": 2,
      "name": "Function Extraction & Call Graph Construction",
      "description": "Extracts functions from source files across supported languages, parses code into blocks, handles specification and info annotations, and constructs inter-procedural call graphs.",
      "modules": [
        {
          "name": "extract",
          "description": "Language-aware function extraction from source files. Defines per-language comment/spec formats, keyword sets, and block-splitting rules for C, C++, Python, Rust, Go, Java, JavaScript, TypeScript, and CUDA. Writes extracted functions to fm_agent/extracted_functions/ with embedded language markers and handles incremental re-extraction on resume.",
          "source_files": ["src/extract.py"]
        },
        {
          "name": "parser",
          "description": "Parses extracted function files into structured representations. Splits code into logical blocks respecting brace depth and indentation, extracts [SPEC] annotations as formal pre/post-conditions, and reads [INFO] blocks that encode caller expectations passed across function boundaries. Used by the reasoner to interpret annotated source files.",
          "source_files": ["src/parser.py"]
        },
        {
          "name": "call_graph_edges",
          "description": "Manages static and supplemental call graph edges. Loads static edges from language-specific analyzers and merges user-provided supplemental edges (for indirect call relationships like syscall dispatch). Normalizes fully-qualified function names and validates edge structures.",
          "source_files": ["src/call_graph_edges.py"]
        },
        {
          "name": "languages",
          "description": "Package of language-specific function extractors and call edge analyzers. Each module handles one language's syntax for discovering function definitions and identifying caller-callee relationships. The registry module provides unified batch extraction and call-edge dispatch. The codegraph module initializes an optional codegraph index for accelerated symbol resolution.",
          "source_files": [
            "src/languages/__init__.py",
            "src/languages/c.py",
            "src/languages/cpp.py",
            "src/languages/python.py",
            "src/languages/rust.py",
            "src/languages/go.py",
            "src/languages/java.py",
            "src/languages/javascript.py",
            "src/languages/typescript.py",
            "src/languages/erlang.py",
            "src/languages/codegraph.py",
            "src/languages/registry.py"
          ]
        }
      ],
      "depends_on_phases": [1]
    },
    {
      "phase": 3,
      "name": "Scope Analysis & Layer Organization",
      "description": "Identifies relevant functions from developer intent for incremental analysis, builds dependency-ordered top-down layers from call graphs, and creates batched prompt files for parallel specification generation.",
      "modules": [
        {
          "name": "scope",
          "description": "Function-level localization for incremental mode. Given a developer intent description (feature request, bug report, or change description) and a set of changed files, narrows them to the specific functions most likely to need modification using a two-stage process: heuristic scoring based on traceback names, code identifiers, class references, and body overlap; and optional LLM re-ranking for files with many candidates. Outputs ranked function lists consumed by the incremental reasoner.",
          "source_files": ["src/scope.py"]
        },
        {
          "name": "generate_topdown_layers",
          "description": "Builds dependency-ordered top-down layers from intra-phase call graphs. Reads extracted functions and static call edges to construct per-phase call graphs, performs topological layering so that callees are assigned to lower layers than their callers, and writes per-phase layer metadata JSON files. Supports incremental updates for specific phases and merges supplemental call edges.",
          "source_files": ["src/generate_topdown_layers.py"]
        },
        {
          "name": "generate_batch_prompts",
          "description": "Creates batched prompt files for parallel specification generation. Groups functions within each top-down layer into batches capped by token budget, writes per-batch Markdown prompt files listing functions to spec, and produces a manifest.json tracking each batch's function membership and pending status. Also handles cross-phase function references and comment-language normalization.",
          "source_files": ["src/generate_batch_prompts.py"]
        }
      ],
      "depends_on_phases": [2]
    },
    {
      "phase": 4,
      "name": "Specification Generation & Code Reasoning",
      "description": "Generates behavioral correctness specifications via LLM agents, splits functions into granular blocks, and performs block-by-block Hoare-style reasoning to verify code against specifications.",
      "modules": [
        {
          "name": "prompts",
          "description": "Constructs and manages LLM prompts for the reasoning pipeline. Two primary prompt types: block post-condition generation prompts that ask the model to compute the strongest post-condition after executing a code block given a pre-condition, and spec implication checking prompts that verify whether a computed post-condition logically implies the specification's expected post-condition. Includes JSON response parsing with structured output validation.",
          "source_files": ["src/prompts.py"]
        },
        {
          "name": "reasoner",
          "description": "Performs block-by-block Hoare-style reasoning. Splits functions into granular blocks respecting a configurable minimum line count, computes brace-depth-aware block boundaries, and iterates block-by-block: generates the post-condition of each block via LLM, checks whether the accumulated post-condition satisfies the function's [SPEC], and reports MISMATCH when the actual behavior diverges from the specification. Handles sanitization of spec strings and brace-level adjustment for partial blocks.",
          "source_files": ["src/reasoner.py"]
        }
      ],
      "depends_on_phases": [3]
    },
    {
      "phase": 5,
      "name": "Bug Diagnosis & Verification",
      "description": "Orchestrates streaming reasoning across extracted functions, validates specification mismatches, generates and executes probe scripts to reproduce bugs, and produces structured bug reports with root cause analysis.",
      "modules": [
        {
          "name": "verification",
          "description": "Orchestrates streaming reasoning and bug validation. Pipes extracted functions through the reasoner as specifications become available, collecting [SPEC] blocks from concurrently running spec-generation agents. When a MISMATCH is detected, invokes an OpenCode bug-validation agent that: examines the discrepancy between spec and actual post-condition, identifies the responsible code statements, constructs a probe script to reproduce the bug, executes it to confirm or deny, and writes a structured bug report to fm_agent/bug_validation/. Maintains a summary.json aggregating confirmed and unconfirmed bug counts.",
          "source_files": ["src/verification.py"]
        }
      ],
      "depends_on_phases": [4]
    },
    {
      "phase": 6,
      "name": "Alternative Pipeline Entry Points",
      "description": "Provides alternative pipeline modes for scope-restricted reasoning from a specific entry function and for incremental change analysis that re-checks only modified code against a previous run baseline.",
      "modules": [
        {
          "name": "entry_reasoning_pipeline",
          "description": "Implements the entry-point-scoped reasoning pipeline. Starting from a user-specified entry function and optional end functions, traces the call graph to identify all on-chain functions, extracts and specs only those functions, generates per-phase top-down layers, and runs the full spec-generation, reasoning, and bug-validation workflow restricted to the call-chain subgraph. Supports --only-spec mode to stop after specification generation.",
          "source_files": ["src/entry_reasoning_pipeline.py"]
        },
        {
          "name": "incremental_reasoner",
          "description": "Implements the incremental analysis pipeline. Diffs the current codebase against the commit recorded by a previous run, identifies changed functions via git diff and call-graph impact analysis, uses scope.py to narrow changed files to the specific functions most relevant to the developer's intent, re-generates specifications only for affected functions, and re-runs reasoning and bug validation on the impacted subgraph. Falls back to a full pipeline run when no previous version.log baseline exists.",
          "source_files": ["src/incremental_reasoner.py"]
        }
      ],
      "depends_on_phases": [1, 2, 3, 4, 5]
    }
  ]
}
"}

